    { "step": 3, "action": "query", "database": "kvikkleire", "purpose": "load quick-clay hazard polygons (kartleggingsomrade) with geometry" },
    { "step": 4, "action": "query", "database": "aktsomhetskart_jord_flomskred", "purpose": "load soil- and flood-landslide hazard polygons with geometry" },
    { "step": 5, "action": "spatial_join", "database": null, "purpose": "intersect buildings (step 1) with flood hazard (step 2)" },
    { "step": 6, "action": "spatial_join", "database": null, "purpose": "intersect result (step 5) with quick-clay hazard (step 3)" },
    { "step": 7, "action": "spatial_join", "database": null, "purpose": "intersect result (step 6) with soil/flood-landslide hazard (step 4)" },
    { "step": 8, "action": "limit", "database": null, "purpose": "limit final results to 10 buildings" }
  ]
}

